def content(t):
 rows=''.join(f'<tr><td>{html.escape(a)}</td><td>{html.escape(b)}</td></tr>' for a,b in t['rows'])
 notes=''.join(f'<li>{html.escape(n)}</li>' for n in t['notes'])
 return f'<table><thead><tr><th>Shortcut / reminder</th><th>Use it for</th></tr></thead><tbody>{rows}</tbody></table><pre>{html.escape(t["code"])}</pre><ul>{notes}</ul>'
